package com.bank.forensics;

import java.util.logging.Logger;

public class LogForensics {

    private static final Logger log = Logger.getLogger(LogForensics.class.getName());

    public int longestCommonSubstring(String a, String b) {
        int m = a.length(), n = b.length();
        int[][] dp = new int[m + 1][n + 1];
        int best = 0;                                  // answer is the biggest cell
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (a.charAt(i - 1) == b.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + 1;    // extend contiguous run
                    best = Math.max(best, dp[i][j]);
                } else {
                    dp[i][j] = 0;                       // mismatch breaks the run
                }
            }
        }
        final int result = best;
        log.info(() -> "Longest common substring length = " + result);
        return result;
    }
}
