package com.bank.forensics;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class LcsSubstringDemo {

    private static final Logger log = Logger.getLogger(LcsSubstringDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Log Forensics (Longest Common Substring)");
        LogForensics forensics = new LogForensics();
        log.info("'ABABC' vs 'BABCA' → " + forensics.longestCommonSubstring("ABABC", "BABCA")); // 4
        log.info("'abc' vs 'xyz' → " + forensics.longestCommonSubstring("abc", "xyz"));          // 0
    }
}
